namespace sv_7f995a2aac4043038660c42cc16d251b.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> Warehouses { get; } =
    [
        new("WH-001", "Warehouse A - Main Distribution"),
        new("WH-002", "Warehouse B - East Regional"),
        new("WH-003", "Warehouse C - West Regional"),
        new("WH-004", "Warehouse D - Cold Storage"),
    ];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record Warehouse(string Id, string Name);

namespace sv_7f995a2aac4043038660c42cc16d251b.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Provides polling and a notification event so all subscribed components update together.
/// </summary>
public class InventoryAlertService : IAsyncDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Task? _pollingTask;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by components to start polling. Uses reference counting so polling
    /// runs as long as at least one subscriber is active.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _pollingTask = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Called by components when they no longer need polling.
    /// Stops the timer when the last subscriber leaves.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
        }
    }

    /// <summary>
    /// Triggers an immediate refresh (e.g., after warehouse changes).
    /// </summary>
    public async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Do an initial fetch immediately
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                LowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
                OnAlertCountChanged?.Invoke();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async void HandleWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            await RefreshAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _cts?.Cancel();

        if (_pollingTask is not null)
        {
            try { await _pollingTask; } catch (OperationCanceledException) { }
        }

        _timer?.Dispose();
        _cts?.Dispose();
    }
}

